/// <summary>
/// This is a service class for tier rate calculation.
/// </summary>
[
SRSReportParameterAttribute(classStr(METTierRateCalculationContract))
]
public class METTierRateCalculationService extends SysOperationServiceBase
{
    TAMRebateDate rebateDateOutsideDateRange;
}

Method.Source:
/// <summary>
/// This method starts the process for calculating the tier rates.
/// </summary>
/// <param name = "_contract">_contract</param>
public void process(METTierRateCalculationContract _contract)
{
    FiscalCalendarPeriod fiscalCalendarPeriod;
    FiscalCalendar fiscalCal;
    FiscalCalendarYear fiscalCalYear;
    FiscalCalendarID calendarId = FiscalCalendar::find(Ledger::fiscalCalendar(CompanyInfo::current())).CalendarId;

    FromDate fromDate = _contract.parmFromDate();
    FromDate toDate = _contract.parmToDate();

    ttsbegin;

    select firstonly METNoOfWeeksForPeriod from fiscalCalendarPeriod
        exists join fiscalCalYear
            where fiscalCalendarPeriod.FiscalCalendarYear == fiscalCalYear.RecId
        exists join fiscalCal
            where fiscalCal.RecId == fiscalCalYear.FiscalCalendar
            && fiscalCal.CalendarId == calendarId
            && fiscalCalendarPeriod.Type == FiscalPeriodType::Operating
            && ((fiscalCalendarPeriod.StartDate >= _contract.parmFromDate() && fiscalCalendarPeriod.StartDate <= _contract.parmToDate()) ||
            (fiscalCalendarPeriod.EndDate >= _contract.parmFromDate() && fiscalCalendarPeriod.EndDate <= _contract.parmToDate()) ||
        (fiscalCalendarPeriod.startDate <= _contract.parmFromDate() && fiscalCalendarPeriod.endDate >= _contract.parmToDate()));

    int weekPeriod = 0;
    int calendarMonth = 0;

    if (fiscalCalendarPeriod.METNoOfWeeksForPeriod == METNoOfWeeksForPeriod::Five)
    {
        calendarMonth = 5;
    }
    else if (fiscalCalendarPeriod.METNoOfWeeksForPeriod == METNoOfWeeksForPeriod::Four)
    {
        calendarMonth = 4;
    }
    else if(fiscalCalendarPeriod.METNoOfWeeksForPeriod == METNoOfWeeksForPeriod::Empty)
    {
        throw error("@MET:SetNoOfWeeks");
    }

    TAMRebateDeal rebateDeal;
    TAMRebateTable rebateTable;
    TAMRebateLine rebateLine;
    METTierRebateTrans tierRebateTrans;
    METTierRateTrans tierRateTrans;
    TAMRebateDate rebateDate;
    CustInvoiceTrans custInvoiceTrans;
    CustInvoiceJour custInvoiceJour;
    CustTable custTable;

    select firstonly Deal,RecId from rebateDeal
    where rebateDeal.Deal == _contract.parmRebateDealRecId();

    // 232902 Validation to stop processing for same date transaction
    select firstonly RecId from tierRateTrans
            where tierRateTrans.TAMRebateDealId == rebateDeal.Deal &&
            tierRateTrans.FromDate == _contract.parmFromDate() &&
            tierRateTrans.ToDate == _contract.parmToDate();

    if (tierRateTrans.RecId != 0)
    {
        throw error("@MET:METTierRateTransValidation");
    }

    delete_from tierRateTrans
        where tierRateTrans.TAMRebateDealId == rebateDeal.Deal;

    while select rebateTable
    where rebateTable.METTierLineType == METTierLineType::Rate
    && rebateTable.RebateDeal == rebateDeal.RecId
    {
        int i = 2;

        GUPPricingRuleCopy pricingRuleCopyCustHeader;
        Query custQuery;

        if (rebateTable.PricingRuleHeader)
        {
            pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(rebateTable.PricingRuleHeader));
            custQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopyCustHeader).build();
        }

        while select custInvoiceTrans join custInvoiceJour
        where custInvoiceJour.SalesId == custInvoiceTrans.SalesId
        && custInvoiceJour.InvoiceId == custInvoiceTrans.InvoiceId
        && custInvoiceJour.InvoiceDate == custInvoiceTrans.InvoiceDate
        && custInvoiceJour.numberSequenceGroup == custInvoiceTrans.numberSequenceGroup
        && custInvoiceTrans.InvoiceDate >= _contract.parmFromDate()
        && custInvoiceTrans.InvoiceDate <= _contract.parmToDate()
        join RecId from custTable
            where custTable.AccountNum == custInvoiceJour.OrderAccount
        {
            if (custQuery)
            {

                SysQuery::findOrCreateRange(custQuery.dataSourceTable(tableNum(CustTable)), fieldNum(CustTable, RecId)).value(queryValue(custTable.RecId));
                QueryRun queryRun = new QueryRun(custQuery);

                custQuery.firstOnly1(true);

                if (!queryRun.next())
                {
                    continue;
                }
            }

            i = 2 ;

            while (i > 0)
            {
                tierRebateTrans.clear();
                tierRebateTrans.Claimed = NoYes::No;
                tierRebateTrans.CurrencyCode = custInvoiceTrans.CurrencyCode;
                tierRebateTrans.DefaultDimension = custInvoiceTrans.DefaultDimension;
                tierRebateTrans.InventDimId = rebateTable.InventDimId;
                tierRebateTrans.ExcludeRebateManagement = NoYes::No;
                tierRebateTrans.ItemId = custInvoiceTrans.ItemId;
                tierRebateTrans.PostingAmount = custInvoiceTrans.LineAmount;
                tierRebateTrans.RefCompanyId = custInvoiceTrans.DataAreaId;
                tierRebateTrans.RefRecId = custInvoiceTrans.RecId;
                tierRebateTrans.RefTableId = custInvoiceTrans.TableId;
                tierRebateTrans.RebateAmount  = custInvoiceTrans.LineAmount;
                tierRebateTrans.RebateFromDate = _contract.parmFromDate();
                tierRebateTrans.RebateToDate = _contract.parmToDate();
                tierRebateTrans.RebateId = rebateTable.RebateId;
                tierRebateTrans.RebateQty = custInvoiceTrans.Qty;
                tierRebateTrans.RebateRefAccount = custInvoiceJour.OrderAccount;
                tierRebateTrans.RebateRefAmount = custInvoiceTrans.LineAmount;
                tierRebateTrans.RebateRefDate = custInvoiceTrans.InvoiceDate;
                tierRebateTrans.RebateRefQty = custInvoiceTrans.Qty;
                tierRebateTrans.RebateRefId = custInvoiceJour.SalesId;
                tierRebateTrans.RebateRefSoldToAccount = custInvoiceJour.OrderAccount;
                tierRebateTrans.TAMRebateDealId = rebateTable.TAMRebateDeal().Deal;

                if (i==1)
                {
                    tierRebateTrans.RebateTransactionType = TAMRebateTransactionType::Provision;
                    i--;
                }
                else if (i==2)
                {
                    tierRebateTrans.RebateTransactionType = TAMRebateTransactionType::Rebate;
                    i--;
                }

                // FreeText invoice if freetext = no than salestype journal Dont insert records
                If (rebateTable.IncludeFreeText || (!rebateTable.IncludeFreeText && custInvoiceJour.SalesType == SalesType::Sales))
                {
                    tierRebateTrans.insert();
                }
            }
        }

        select firstonly rebateDate
        where rebateDate.RebateId == rebateTable.RebateId;

        //TransDate fromDate = _contract.parmFromDate();

        if (rebateDate.RebateFromDate <= _contract.parmFromDate() && _contract.parmToDate() <= rebateDate.RebateToDate)
        {
            while select StartDate, EndDate from fiscalCalendarPeriod
                exists join fiscalCalYear
                    where fiscalCalendarPeriod.FiscalCalendarYear == fiscalCalYear.RecId
                exists join fiscalCal
                    where fiscalCal.RecId == fiscalCalYear.FiscalCalendar
                        && fiscalCal.CalendarId == calendarId
                        && fiscalCalendarPeriod.Type == FiscalPeriodType::Operating
                        && ((fiscalCalendarPeriod.StartDate >= _contract.parmFromDate() && fiscalCalendarPeriod.StartDate <= _contract.parmToDate()) ||
                            (fiscalCalendarPeriod.EndDate >= _contract.parmFromDate() && fiscalCalendarPeriod.EndDate <= _contract.parmToDate()) ||
                            (fiscalCalendarPeriod.startDate <= _contract.parmFromDate() && fiscalCalendarPeriod.endDate >= _contract.parmToDate()))
            {
                tierRateTrans.clear();
                tierRateTrans.FromDate = fiscalCalendarPeriod.StartDate;
                tierRateTrans.ToDate = fiscalCalendarPeriod.EndDate;
                tierRateTrans.TAMRebateDealId = rebateDeal.Deal;
                tierRateTrans.RebateTransactionType = TAMRebateTransactionType::Rebate;
                tierRateTrans.RebateId = rebateTable.RebateId;

                select sum(RebateRefAmount) from tierRebateTrans
                    where tierRebateTrans.RebateRefDate >= tierRateTrans.FromDate
                            && tierRebateTrans.RebateRefDate <= tierRateTrans.ToDate
                            && tierRebateTrans.RebateId == rebateTable.RebateId
                            && tierRebateTrans.TAMRebateDealId == tierRateTrans.TAMRebateDealId
                            && tierRebateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate;

                if (tierRebateTrans.RebateRefAmount)
                {                        
                    tierRateTrans.AgEligibleTransAmount = tierRebateTrans.RebateRefAmount;

                    if (calendarMonth)
                    {
                        tierRateTrans.WeeklyAverage = tierRateTrans.AgEligibleTransAmount/calendarMonth;
                    }

                    select firstonly rebateLine
                    where rebateLine.RebateFrom <= tierRateTrans.WeeklyAverage
                    && rebateLine.RebateLimit >= tierRateTrans.WeeklyAverage
                    && rebateLine.RebateId == rebateTable.RebateId;

                    tierRateTrans.EligibleRebate = rebateLine.RebateAmount;

                    tierRateTrans.insert();

                    update_recordSet tierRebateTrans
                    setting METTierRateTransRecID = tierRateTrans.RecId
                        where tierRebateTrans.RebateRefDate >= tierRateTrans.FromDate
                            && tierRebateTrans.RebateRefDate <= tierRateTrans.ToDate
                            && tierRebateTrans.RebateId == rebateTable.RebateId
                            && tierRebateTrans.TAMRebateDealId == tierRateTrans.TAMRebateDealId
                            && tierRebateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate;

                }
            }

            // Bug 289018: CB201 - Volumetric Tier Rebates - Calculate Rate picking up incorrect dates
            this.createTierRateTransactions(fromDate, toDate, rebateTable, TAMRebateTransactionType::Provision);                
        }

    }

    ttscommit;
}

/// <summary>
/// Bug 289018: CB201 - Volumetric Tier Rebates - Calculate Rate picking up incorrect dates
/// Copied from TAMRebateFindTransRebateTable\findTransactions so we can reuse the same standard logic which calculates the TAMRebateDateTrans
/// From and To date
/// </summary>
/// <param name = "_fromDate">From date</param>
/// <param name = "_toDate">To date</param>
/// <param name = "_rebateTable">Rebate management number</param>
/// <param name = "_rebateTransactionType">Rebate transaction type</param>
protected void createTierRateTransactions(FromDate _fromDate, ToDate _toDate, TAMRebateTable _rebateTable, TAMRebateTransactionType _rebateTransactionType)
{
    this.createTierRateTransactionFromDateOutsideDateRange(_fromDate, _toDate, _rebateTable, _rebateTransactionType);

    this.createTierRateTransactionFromDateInsideDateRange(_fromDate, _toDate, _rebateTable, _rebateTransactionType);
}

/// <summary>
/// Bug 289018: CB201 - Volumetric Tier Rebates - Calculate Rate picking up incorrect dates
/// Copied from TAMRebateFindTransRebateTable\findTransactionsRebateFromDateOutsideDateRange so we can reuse the same standard logic which calculates the TAMRebateDateTrans
/// From and To date
/// </summary>
/// <param name = "_fromDate">From date</param>
/// <param name = "_toDate">To date</param>
/// <param name = "_rebateTable">Rebate management number</param>
/// <param name = "_rebateTransactionType">Rebate transaction type</param>
protected void createTierRateTransactionFromDateOutsideDateRange(FromDate _fromDate, ToDate _toDate, TAMRebateTable _rebateTable, TAMRebateTransactionType _rebateTransactionType)
{
    select firstonly rebateDateOutsideDateRange
        order by RebateFromDate desc
            where rebateDateOutsideDateRange.RebateFromDate <= _fromDate
               && rebateDateOutsideDateRange.RebateToDate >= _fromDate
               && rebateDateOutsideDateRange.RebateId == _rebateTable.rebateId;

    TAMRebateDatePeriod rebateDatePeriod = TAMRebateDatePeriod::newFromRebateDateAndTransactionType(rebateDateOutsideDateRange, _rebateTransactionType);

    FromDate rebateFromDate = rebateDatePeriod.findFromDate(_fromDate);

    while (rebateFromDate <= rebateDateOutsideDateRange.RebateToDate && rebateDateOutsideDateRange.RebateToDate != datenull())
    {
        ToDate rebateToDate = rebateDatePeriod.findToDate(rebateFromDate);

        this.createTierRateTransaction(max(rebateFromDate, rebateDateOutsideDateRange.RebateFromDate), 
                                       min(rebateToDate, rebateDateOutsideDateRange.RebateToDate),
                                       _rebateTable, 
                                       _rebateTransactionType);

        if (rebateToDate >= _toDate)
        {
            break;
        }

        rebateFromDate = rebateToDate + 1;
    }
}

/// <summary>
/// Bug 289018: CB201 - Volumetric Tier Rebates - Calculate Rate picking up incorrect dates
/// Copied from TAMRebateFindTransRebateTable\findTransactionsRebateFromDateInsideDateRange so we can reuse the same standard logic which calculates the TAMRebateDateTrans
/// From and To date
/// </summary>
/// <param name = "_fromDate">From date</param>
/// <param name = "_toDate">To date</param>
/// <param name = "_rebateTable">Rebate management number</param>
/// <param name = "_rebateTransactionType">Rebate transaction type</param>
protected void createTierRateTransactionFromDateInsideDateRange(FromDate _fromDate, ToDate _toDate, TAMRebateTable _rebateTable, TAMRebateTransactionType _rebateTransactionType)
{
    TAMRebateDate rebateDateInsideDateRange;

    select rebateDateInsideDateRange
        order by RebateFromDate asc
        where rebateDateInsideDateRange.RebateFromDate > _fromDate
            && rebateDateInsideDateRange.RebateFromDate <= _toDate
            && rebateDateInsideDateRange.RebateId == _rebateTable.rebateId;

    if (!rebateDateOutsideDateRange && !rebateDateInsideDateRange)
    {
        throw error("@RebatesAndDeductions:CannotCreateRebateTransForDataRange");
    }

    TAMRebateDatePeriod rebateDatePeriod = TAMRebateDatePeriod::newFromRebateDateAndTransactionType(rebateDateInsideDateRange, _rebateTransactionType);

    FromDate rebateFromDate = rebateDatePeriod.findFromDate(rebateDateInsideDateRange.RebateFromDate);

    while (rebateDateInsideDateRange && rebateFromDate <= _toDate)
    {
        ToDate rebateToDate = rebateDatePeriod.findToDate(rebateFromDate);

        this.createTierRateTransaction(max(rebateFromDate, rebateDateInsideDateRange.RebateFromDate),
                                       min(rebateToDate, rebateDateInsideDateRange.RebateToDate),
                                       _rebateTable, 
                                       _rebateTransactionType);

        if (rebateToDate >= rebateDateInsideDateRange.RebateToDate && rebateDateInsideDateRange.RebateToDate != datenull())
        {
            next rebateDateInsideDateRange;
            rebateDatePeriod = TAMRebateDatePeriod::newFromRebateDateAndTransactionType(rebateDateInsideDateRange, _rebateTransactionType);
        }

        rebateFromDate = rebateToDate + 1;
    }
}

/// <summary>
/// Bug 289018: CB201 - Volumetric Tier Rebates - Calculate Rate picking up incorrect dates
/// Copied and refactored the existing code to create the Provision METTierRateTrans record
/// </summary>
/// <param name = "_fromDate">From date</param>
/// <param name = "_toDate">To date</param>
/// <param name = "_rebateTable">Rebate management number</param>
/// <param name = "_rebateTransactionType">Rebate transaction type</param>
protected void createTierRateTransaction(FromDate _fromDate, ToDate _toDate, TAMRebateTable _rebateTable, TAMRebateTransactionType _rebateTransactionType)
{
    METTierRebateTrans tierRebateTrans;
    METTierRateTrans tierRateTrans; 
    TAMRebateLine rebateLine;

    tierRateTrans.clear();
    tierRateTrans.FromDate = _fromDate;
    tierRateTrans.ToDate = _toDate;
    tierRateTrans.TAMRebateDealId = TAMRebateDeal::find(_rebateTable.RebateDeal).Deal;
    tierRateTrans.RebateTransactionType = _rebateTransactionType;
    tierRateTrans.RebateId = _rebateTable.RebateId;

    select sum(RebateRefAmount) from tierRebateTrans
                where tierRebateTrans.RebateRefDate >= tierRateTrans.FromDate
                && tierRebateTrans.RebateRefDate <= tierRateTrans.ToDate
                && tierRebateTrans.RebateId == _rebateTable.RebateId
                && tierRebateTrans.TAMRebateDealId == tierRateTrans.TAMRebateDealId
                && tierRebateTrans.RebateTransactionType == _rebateTransactionType;

    if (tierRebateTrans.RebateRefAmount)
    {
        tierRateTrans.AgEligibleTransAmount = tierRebateTrans.RebateRefAmount;

        select firstonly rebateLine
                where rebateLine.RebateFrom <= tierRateTrans.AgEligibleTransAmount
                && rebateLine.RebateLimit >= tierRateTrans.AgEligibleTransAmount
                && rebateLine.RebateId == _rebateTable.RebateId;

        tierRateTrans.EligibleRebate = rebateLine.RebateAmount;

        tierRateTrans.insert();

        update_recordSet tierRebateTrans
            setting METTierRateTransRecID = tierRateTrans.RecId
                where tierRebateTrans.RebateRefDate >= tierRateTrans.FromDate
                && tierRebateTrans.RebateRefDate <= tierRateTrans.ToDate
                && tierRebateTrans.RebateId == _rebateTable.RebateId
                && tierRebateTrans.TAMRebateDealId == tierRateTrans.TAMRebateDealId
                && tierRebateTrans.RebateTransactionType == _rebateTransactionType;
    }        
}
